// THE STRATA SHELL on cookrew.dev: level 0 at /me (D2), its assets under
// /strata/, carried in a SECOND bundle (D3).
//
// The registry's own bundle is one ConfigMap and already close to its 1 MiB
// ceiling, so the shell's built files travel in a file of their own —
// generated by `node scripts/registry-assets.mjs --shell <built dir>` and
// mounted beside the registry from a second ConfigMap. The registry reads it
// once at boot (`--shell-assets <file>`). Absent or malformed, /me stays the
// classic account page: a registry deployed before its shell is never a
// blank page.

import { readFileSync } from 'node:fs'
import type { ServerResponse } from 'node:http'
import type { BundledAsset } from './assets-bundle'
import { STRATA_SHELL_CSP, type Page } from './site-shell'

/** Where the shell's files are served; the shell is built with this as its base. */
export const SHELL_PREFIX = '/strata/'

export interface ShellBundle {
  /** Content hash of every file, for the page's own cache key. */
  version: string
  /** The built index.html, its asset references already under SHELL_PREFIX. */
  index: string
  /** Path under SHELL_PREFIX ('assets/index-3f9a.js') → the file. */
  files: Readonly<Record<string, BundledAsset>>
}

const FILE_NAME = /^[A-Za-z0-9._-]+(?:\/[A-Za-z0-9._-]+)*$/

/** The bundle as the second ConfigMap holds it, or null with the reason logged. */
export function readShellBundle(text: string): ShellBundle | null {
  try {
    const raw = JSON.parse(text) as Partial<ShellBundle>
    if (typeof raw.version !== 'string' || typeof raw.index !== 'string' || typeof raw.files !== 'object' || raw.files === null) return null
    const files: Record<string, BundledAsset> = {}
    for (const [name, file] of Object.entries(raw.files)) {
      if (!FILE_NAME.test(name) || name.split('/').includes('..')) return null
      if (typeof file?.type !== 'string' || typeof file.body !== 'string') return null
      files[name] = { type: file.type, body: file.body, ...(file.encoding === 'base64' ? { encoding: 'base64' as const } : {}) }
    }
    return { version: raw.version, index: raw.index, files }
  } catch {
    return null
  }
}

export function loadShellBundle(file: string | null | undefined, log: (message: string) => void = () => undefined): ShellBundle | null {
  if (!file) return null
  try {
    const bundle = readShellBundle(readFileSync(file, 'utf8'))
    if (bundle === null) log(`strata shell: ${file} is not a shell bundle; /me stays the account page`)
    return bundle
  } catch (error) {
    log(`strata shell: could not read ${file} (${error instanceof Error ? error.message : String(error)}); /me stays the account page`)
    return null
  }
}

/**
 * The shell's page: its own index.html under the app CSP plus frame-src
 * 'self' (the dive embeds the desktop's companion, same-origin, through the
 * relay prefix). Rendered for one reader, so never cached.
 */
export function shellPage(bundle: ShellBundle): Page {
  return {
    status: 200,
    headers: {
      'content-type': 'text/html; charset=utf-8',
      'content-security-policy': STRATA_SHELL_CSP,
      'x-content-type-options': 'nosniff',
      'referrer-policy': 'no-referrer',
      'cache-control': 'private, no-store',
      vary: 'cookie'
    },
    body: bundle.index
  }
}

/** GET /strata/<path>: a built file. */
export function serveShellAsset(response: ServerResponse, bundle: ShellBundle | null, name: string): boolean {
  if (bundle === null || !Object.prototype.hasOwnProperty.call(bundle.files, name)) return false
  const asset = bundle.files[name]
  const payload = Buffer.from(asset.body, asset.encoding === 'base64' ? 'base64' : 'utf8')
  response.writeHead(200, {
    'content-type': asset.type,
    'content-length': String(payload.byteLength),
    // The build hashes what it puts under assets/; anything else keeps its name across builds.
    'cache-control': name.startsWith('assets/') ? 'public, max-age=31536000, immutable' : 'public, max-age=300',
    'x-content-type-options': 'nosniff'
  })
  response.end(payload)
  return true
}
